INSERT INTO public.notification_template (template_code, channel, target, title, body) VALUES
  ('FOLLOWUP_SENT', 'PUSH', 'TECHNICIAN', '독촉·전달', E'#{접수번호} #{독촉회차}차 전달\n#{전달내용}\n알림에서 확인하고 회신해 주세요.'),
  ('FOLLOWUP_ADMIN', 'PUSH', 'ADMIN', '독촉·전달', E'#{독촉회차}차 전달: #{전달내용}'),
  ('FOLLOWUP_REPLIED', 'PUSH', 'ADMIN', '독촉·전달 회신', E'#{접수번호} 전달에 기사가 회신했습니다.\n#{회신}'),
  ('SAFETY_INCIDENT', 'PUSH', 'ADMIN', '안전사고 접수', E'#{사고번호} #{피해유형} 안전사고가 접수되었습니다. 안전사고 관리에서 확인해 주세요.'),
  ('SAFETY_ESCALATED', 'PUSH', 'ADMIN', '[경영진 보고] 안전사고', E'#{사고번호} #{피해유형} 안전사고가 언론·인터넷에 알려졌습니다. 즉시 확인해 주세요.'),
  ('AS_RECEIVED', 'ALIMTALK', 'CUSTOMER', 'AS 접수 안내', E'#{고객명}님, AS 요청이 접수되었습니다.\nAS 번호: #{AS번호}\n#{보증안내}\n확인 후 연락드리겠습니다.'),
  ('AS_SCHEDULED', 'ALIMTALK', 'CUSTOMER', 'AS 재방문 안내', E'#{고객명}님, AS 재방문 일정이 잡혔습니다.\n방문 일시: #{방문일시}\n접수번호: #{접수번호}\n금액: #{금액}\n문의: #{거점전화}'),
  ('AS_REJECTED', 'ALIMTALK', 'CUSTOMER', 'AS 요청 결과 안내', E'#{고객명}님, 요청하신 AS(#{AS번호})는 처리하기 어렵습니다.\n사유: #{사유}\n문의: #{거점전화}'),
  ('INQUIRY_ANSWERED', 'ALIMTALK', 'CUSTOMER', '1:1 문의 답변 안내', E'#{고객명}님, 1:1 문의에 답변이 등록되었습니다.\n고객센터 > 1:1 문의에서 확인해 주세요.'),
  ('REVISIT_11M', 'ALIMTALK', 'CUSTOMER', '재방문 안내', E'#{고객명}님, 에어컨 청소를 받으신 지 #{경과개월}개월이 지났어요.\n더워지기 전에 미리 예약해 보세요.\n예약하기: #{예약링크}\n수신을 원하지 않으시면 마이 > 동의 관리에서 해제할 수 있어요.')
ON CONFLICT (template_code) DO NOTHING;
--> statement-breakpoint
INSERT INTO public.faq (category, audience, question, answer, is_published, sort_order)
SELECT v.category, 'CUSTOMER', v.question, v.answer, true, v.sort_order FROM (VALUES
  ('PRICE', '추가요금이 생길 수 있나요?', '오염이 심하거나 높은 곳 작업 등은 현장에서 기사님이 먼저 설명하고, 고객님이 동의한 경우에만 추가돼요.', 10),
  ('RESERVATION', '예약을 바꾸거나 취소하려면요?', '내 예약 > 예약 상세 > 일정 변경·취소에서 할 수 있어요. 기사님이 출발한 뒤에는 고객센터로 연락해 주세요.', 20),
  ('PRICE', '결제는 언제 하나요?', '예약할 때 미리 결제하거나, 방문한 날 현장에서 결제할 수 있어요.', 30),
  ('AS', '청소 후 문제가 생기면 어떻게 하나요?', '내 예약 > 예약 상세에서 [AS 요청]을 눌러 주세요. 작업 완료 후 보증기간(기본 30일) 안이면 무상으로 다시 방문해요.', 40)
) AS v(category, question, answer, sort_order)
WHERE NOT EXISTS (SELECT 1 FROM public.faq);
--> statement-breakpoint
-- 재방문 자동 캠페인(F-ADM-CRM-01) 기본 행: 1개만 두고 A-CRM-010에서 규칙을 고친다. 처음엔 중지(STOPPED) 상태로 시작한다.
INSERT INTO public.campaign (name, campaign_type, target_rule_json, template_id, schedule_type, status)
SELECT '재방문 자동 안내', 'REVISIT_AUTO', '{"branchIds":[]}'::jsonb, t.id, 'DAILY_AUTO', 'STOPPED'
FROM public.notification_template t
WHERE t.template_code = 'REVISIT_11M' AND NOT EXISTS (SELECT 1 FROM public.campaign WHERE campaign_type = 'REVISIT_AUTO');
